referenceSolutions.javascript:
export function longestPalindromeLength(text        )         {
  const counts = new Map                (); for (const c of text) counts.set(c, (counts.get(c) ?? 0) + 1); let result = 0, odd = false; for (const count of counts.values()) { result += count - count % 2; if (count % 2) odd = true; } return result + (odd ? 1 : 0);
}

referenceSolutions.typescript:
export function longestPalindromeLength(text: string): number {
  const counts = new Map<string, number>(); for (const c of text) counts.set(c, (counts.get(c) ?? 0) + 1); let result = 0, odd = false; for (const count of counts.values()) { result += count - count % 2; if (count % 2) odd = true; } return result + (odd ? 1 : 0);
}
